        return num1 + num2
    elif operation == 2:
        return num1 - num2
    elif operation == 3:
        return num1 * num2
    elif operation == 4:
        if num2 == 0:
            return "Division by zero is not allowed."
        else:
            return num1 / num2
    else:
        return "Invalid operation."

